<?php require_once __DIR__.'/../includes/functions.php';$u=require_login();verify_csrf();$to=(int)($_POST['ratee_id']??0);$n=(int)($_POST['rating']??0);if($to===(int)$u['id']||$n<1||$n>5){flash('danger','Choose a valid partner and a rating from one to five.');go('../student/settings.php');}$q=db()->prepare("SELECT COUNT(*) FROM study_requests WHERE status='accepted' AND ((sender_id=? AND receiver_id=?) OR (sender_id=? AND receiver_id=?))");$q->execute([(int)$u['id'],$to,$to,(int)$u['id']]);if(!$q->fetchColumn()){flash('danger','Ratings are limited to accepted study partners.');go('../student/settings.php');}try{db()->prepare('INSERT INTO ratings(rater_id,ratee_id,rating,feedback) VALUES(?,?,?,?)')->execute([(int)$u['id'],$to,$n,substr(trim($_POST['feedback']??''),0,500)]);notify($to,$u['name'].' left feedback for your study partnership.','profile.php');flash('success','Thank you for sharing feedback.');}catch(PDOException $e){flash('warning','You have already rated this study partner.');}go('../student/settings.php');
